Copy File.code:
// Make a copy of a file, optionally renaming it and placing it in another folder.
// The googledrive adaptor has no helper for this, so call the Drive API directly.
fn(async state => {
  const res = await fetch(`https://www.googleapis.com/drive/v3/files/${state.data.fileId}/copy?supportsAllDrives=true`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${state.configuration.accessToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      name: `Copy of ${state.data.fileName}`,
      parents: [state.configuration.parentFolderId],
    }),
  });
  if (!res.ok) throw new Error(`Drive API error ${res.status}: ${await res.text()}`);
  state.data = await res.json();
  return state;
});

Copy File from Another Service.code:
// 1) Download the file from another service's URL (e.g. a form attachment link).
fn(async state => {
  const res = await fetch(state.data.fileUrl);
  if (!res.ok) throw new Error(`Download failed: ${res.status}`);
  // create() expects base64-encoded content.
  state.fileBase64 = Buffer.from(await res.arrayBuffer()).toString('base64');
  return state;
});

// 2) Upload it to Drive.
create(
  // 1) Base64 file content.
  $.fileBase64,
  // 2) File name in Drive.
  $.data.fileName,
  // 3) Optional target folder.
  { folderId: $.configuration.parentFolderId }
);

Create File From Text.code:
// Create a new file from a string of text.
create(
