Create Shared Drive.code:
// Create a new shared drive.
// The googledrive adaptor has no helper for this, so call the Drive API directly.
// requestId is an idempotency key: reuse it to safely retry the same create.
fn(async state => {
  const res = await fetch(`https://www.googleapis.com/drive/v3/drives?requestId=${encodeURIComponent(state.data.requestId)}`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${state.configuration.accessToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ name: `${state.data.programmeName} - field reports` }),
  });
  if (!res.ok) throw new Error(`Drive API error ${res.status}: ${await res.text()}`);
  state.data = await res.json();
  return state;
});

