Permanently Delete File.code:
// Permanently delete a file, skipping the trash. This cannot be undone.
// The googledrive adaptor has no helper for this, so call the Drive API directly.
fn(async state => {
  const res = await fetch(`https://www.googleapis.com/drive/v3/files/${state.data.fileId}?supportsAllDrives=true`, {
    method: 'DELETE',
    headers: {
      Authorization: `Bearer ${state.configuration.accessToken}`,
    },
  });
  if (!res.ok) throw new Error(`Drive API error ${res.status}: ${await res.text()}`);
  // A successful delete returns 204 with no body.
  return state;
});

Remove File Access.code:
// Remove one user's access to a file.
// The googledrive adaptor has no helper for permissions, so call the Drive API directly.
fn(async state => {
  const headers = { Authorization: `Bearer ${state.configuration.accessToken}` };
  const base = `https://www.googleapis.com/drive/v3/files/${state.data.fileId}/permissions`;

  // 1) Find the permission id for this user's email.
  const listRes = await fetch(`${base}?fields=permissions(id,emailAddress,role)&supportsAllDrives=true`, { headers });
  if (!listRes.ok) throw new Error(`Drive API error ${listRes.status}: ${await listRes.text()}`);
  const { permissions = [] } = await listRes.json();
  const permission = permissions.find(p => p.emailAddress === state.data.email);
  if (!permission) throw new Error(`${state.data.email} has no access to this file`);

  // 2) Delete that permission.
  const res = await fetch(`${base}/${permission.id}?supportsAllDrives=true`, { method: 'DELETE', headers });
  if (!res.ok) throw new Error(`Drive API error ${res.status}: ${await res.text()}`);
  return state;
});

