Find a File.code:
// Search for files by name. `list` returns matching items on state.data.
list(
  // 1) Folder id to scope the search to (required).
  $.configuration.parentFolderId,
  // 2) List options.
  {
    // Extra Drive query, ANDed with the folder filter: https://developers.google.com/drive/api/guides/search-files
    query: `name = '${$.data.fileName}' and trashed = false`,
    fields: ['id', 'name', 'mimeType', 'modifiedTime'],
  }
);

Find a Folder.code:
// Search for folders by name inside a parent folder (list() requires a folder id).
list($.configuration.parentFolderId, {
  query: `mimeType = 'application/vnd.google-apps.folder' and name = '${$.data.folderName}' and trashed = false`,
  fields: ['id', 'name'],
});

Find or Create File.code:
// Keep the incoming payload: list() replaces state.data with its results.
fn(state => ({ ...state, input: state.data }));

// 1) Look for the file by name in the folder.
list($.configuration.parentFolderId, {
  query: `name = '${$.input.fileName}' and trashed = false`,
  fields: ['id', 'name', 'mimeType', 'modifiedTime'],
  limit: 1,
});

// 2) Nothing found? Upload it (content must be base64).
fnIf(
  state => state.data.length === 0,
  create($.input.fileBase64, $.input.fileName, {
    folderId: $.configuration.parentFolderId,
  })
);

Find or Create Folder.code:
// Keep the incoming payload: list() replaces state.data with its results.
fn(state => ({ ...state, input: state.data }));

// 1) Look for a sub-folder with this name inside the parent folder.
list($.configuration.parentFolderId, {
  query: `mimeType = 'application/vnd.google-apps.folder' and name = '${$.input.folderName}' and trashed = false`,
  fields: ['id', 'name'],
  limit: 1,
});

// 2) Nothing found? Create it. create() only uploads files, so call the Drive API for folders.
fnIf(
  state => state.data.length === 0,
  fn(async state => {
    const res = await fetch('https://www.googleapis.com/drive/v3/files?supportsAllDrives=true', {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${state.configuration.accessToken}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        name: state.input.folderName,
        mimeType: 'application/vnd.google-apps.folder',
        parents: [state.configuration.parentFolderId],
      }),
    });
    if (!res.ok) throw new Error(`Drive API error ${res.status}: ${await res.text()}`);
    state.data = [await res.json()];
    return state;
  })
);

List File Permissions.code:
// List everyone who has access to a file, and their role.
// The googledrive adaptor has no helper for permissions, so call the Drive API directly.
fn(async state => {
  const res = await fetch(`https://www.googleapis.com/drive/v3/files/${state.data.fileId}/permissions?` +
    `fields=permissions(id,type,role,emailAddress,displayName)&supportsAllDrives=true`, {
    headers: {
      Authorization: `Bearer ${state.configuration.accessToken}`,
    },
  });
  if (!res.ok) throw new Error(`Drive API error ${res.status}: ${await res.text()}`);
  // Each permission has a role: owner, organizer, writer, commenter or reader.
  state.data = (await res.json()).permissions;
  return state;
});

